import{c as a,Q as s,j as e,m as i}from"./chunks/framework.8JjYC3xy.js";const u=JSON.parse('{"title":"第十九章：Subagents 与并行会话","description":"用子代理把脏活挪出主对话，用分叉和 worktree 同时推进多条线","frontmatter":{"title":"第十九章：Subagents 与并行会话","description":"用子代理把脏活挪出主对话，用分叉和 worktree 同时推进多条线","lastVerified":"2026-02-24","officialDoc":"https://code.claude.com/docs/zh-CN/sub-agents"},"headers":[],"relativePath":"guide/4-advanced-usage/19-subagents.md","filePath":"guide/4-advanced-usage/19-subagents.md"}'),d={name:"guide/4-advanced-usage/19-subagents.md"};function o(n,t,l,r,p,h){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="第十九章-subagents-与并行会话" tabindex="-1">第十九章：Subagents 与并行会话 <a class="header-anchor" href="#第十九章-subagents-与并行会话" aria-label="Permalink to &quot;第十九章：Subagents 与并行会话&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会用内置子代理省上下文、写出第一个自定义 subagent，并知道什么时候该用分叉、后台会话或 worktree。</p></div><div class="warning custom-block"><p class="custom-block-title">别和&quot;权限模式&quot;搞混</p><ul><li><strong>权限模式</strong>（第十七章）管的是&quot;它能不能不问你就动手&quot;</li><li><strong>Subagent</strong> 管的是&quot;派一个独立的助手去干一件事，只在结束时把结论带回来&quot;</li></ul><p>两者完全无关，不要混为一谈。</p></div><h2 id="一句话说清它解决什么问题" tabindex="-1">一句话说清它解决什么问题 <a class="header-anchor" href="#一句话说清它解决什么问题" aria-label="Permalink to &quot;一句话说清它解决什么问题&quot;">​</a></h2><p>你让它&quot;在整个项目里找出所有写死的超时时间&quot;。它要 <code>grep</code> 几十个文件、读十几个结果——这些搜索结果会<strong>全部留在你的主对话里</strong>，占掉上下文，而你在拿到答案后再也不会看它们第二眼。</p><p>Subagent 的做法：把这件事扔进一个独立的上下文窗口，干完只回一句&quot;在 7 个文件里找到 12 处，都在 <code>src/api/</code> 下，清单如下&quot;。<strong>过程中的噪音不进入你的主对话</strong>。</p><h2 id="你其实已经在用它了" tabindex="-1">你其实已经在用它了 <a class="header-anchor" href="#你其实已经在用它了" aria-label="Permalink to &quot;你其实已经在用它了&quot;">​</a></h2><p>Claude Code 自带几个内置子代理，Claude 会自己判断何时用：</p><table tabindex="0"><thead><tr><th>内置 subagent</th><th>干什么</th><th>特点</th></tr></thead><tbody><tr><td><strong>Explore</strong></td><td>搜代码、找文件、摸清项目结构</td><td>只读，不加载 <code>CLAUDE.md</code>，快</td></tr><tr><td><strong>Plan</strong></td><td>在做计划前收集上下文</td><td>只读，只在计划模式里用</td></tr></tbody></table><p>所以你看到对话里冒出 <code>Explore(Find timeout constants)</code> 这样的行，就是它在派子代理。</p><h2 id="什么时候派子代理-什么时候自己聊" tabindex="-1">什么时候派子代理，什么时候自己聊 <a class="header-anchor" href="#什么时候派子代理-什么时候自己聊" aria-label="Permalink to &quot;什么时候派子代理，什么时候自己聊&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用主对话</th><th>用 subagent</th></tr></thead><tbody><tr><td>需要来回商量、反复微调</td><td>任务自成一体，只要一个结论</td></tr><tr><td>各阶段共享大量上下文（规划→实现→测试）</td><td>中间过程会产出大量你不需要的日志/搜索结果</td></tr><tr><td>改动很小、就几行</td><td>想限制它能用的工具（比如只读）</td></tr><tr><td>慢一点没关系但要快反馈</td><td>想并行推进多条线</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">经验值</p><p><strong>&quot;这会读很多文件/输出很长，但我只想要结论&quot;</strong> —— 出现这个念头时就该派子代理。</p></div><h2 id="写第一个自定义-subagent" tabindex="-1">写第一个自定义 subagent <a class="header-anchor" href="#写第一个自定义-subagent" aria-label="Permalink to &quot;写第一个自定义 subagent&quot;">​</a></h2><p>Subagent 就是一个带 YAML frontmatter 的 Markdown 文件。最简单的做法：直接让 Claude 帮你写。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 ~/.claude/agents/ 里创建一个叫 code-improver 的个人子代理，</span></span>
<span class="line"><span>扫描文件并给出可读性、性能、最佳实践三方面的改进建议。</span></span>
<span class="line"><span>它应该是只读的，用 sonnet 模型。</span></span></code></pre></div><p>它会生成类似这样的文件：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: code-improver</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: 扫描文件并给出可读性、性能、最佳实践方面的改进建议。在写完或修改代码后使用。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tools: Read, Grep, Glob</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model: sonnet</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">你是一个代码改进专家。对每个问题，先解释问题，再展示当前代码，</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">再给出改进后的版本。</span></span></code></pre></div><p>三个字段最关键：</p><table tabindex="0"><thead><tr><th>字段</th><th>作用</th></tr></thead><tbody><tr><td><code>name</code></td><td>调用时用的名字</td></tr><tr><td><code>description</code></td><td><strong>Claude 靠它判断什么时候该派这个代理</strong>，写清楚触发场景</td></tr><tr><td><code>tools</code></td><td>限定它能做什么。只想要建议就只给 <code>Read, Grep, Glob</code></td></tr><tr><td><code>model</code></td><td>可以指定 <code>haiku</code> 这类便宜模型，省钱</td></tr></tbody></table><h3 id="放哪-项目级还是个人级" tabindex="-1">放哪：项目级还是个人级 <a class="header-anchor" href="#放哪-项目级还是个人级" aria-label="Permalink to &quot;放哪：项目级还是个人级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>位置</th><th>生效范围</th><th>适合</th></tr></thead><tbody><tr><td><code>.claude/agents/</code></td><td>当前项目，可提交到 git 与团队共享</td><td>团队约定的审查者、测试跑手</td></tr><tr><td><code>~/.claude/agents/</code></td><td>你机器上所有项目</td><td>个人习惯的工具</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">常见坑</p><p>如果 <code>~/.claude/agents/</code> 这个目录是在会话开始<strong>之后</strong>才创建的，当前会话检测不到。重启 <code>claude</code> 就好。</p></div><h2 id="怎么调用" tabindex="-1">怎么调用 <a class="header-anchor" href="#怎么调用" aria-label="Permalink to &quot;怎么调用&quot;">​</a></h2><p><strong>方式一：自然语言</strong>（Claude 自己决定派不派）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用 code-improver 子代理看看这个项目哪里能改进</span></span></code></pre></div><p><strong>方式二：<code>@</code> 点名</strong>（强制派它）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@&quot;code-reviewer (agent)&quot; 看一下我最近的认证改动</span></span></code></pre></div><p><strong>方式三：整个会话以某个子代理身份运行</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code-reviewer</span></span></code></pre></div><h2 id="前台还是后台" tabindex="-1">前台还是后台 <a class="header-anchor" href="#前台还是后台" aria-label="Permalink to &quot;前台还是后台&quot;">​</a></h2><p>从主对话派出的子代理<strong>默认在后台跑</strong>，你可以继续干别的。它需要权限时，提示会冒到你的主会话里，标明是哪个子代理在请求。</p><p>想让它跑在前台、等它结束（比如你就是要它的结论才能继续），可以直接说&quot;等它完成再继续&quot;，或者关掉 fork 模式：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// settings.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;CLAUDE_CODE_FORK_SUBAGENT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><h2 id="分叉-带着当前上下文派活" tabindex="-1">分叉：带着当前上下文派活 <a class="header-anchor" href="#分叉-带着当前上下文派活" aria-label="Permalink to &quot;分叉：带着当前上下文派活&quot;">​</a></h2><p>普通子代理是<strong>从零开始</strong>的，它不知道你们前面聊了什么。每派一次都要重新解释背景，很浪费。</p><p><code>/subtask</code> 是&quot;分叉&quot;：它继承当前完整对话，等于从你现在的状态复制出一个自己，去干一件旁支的活，干完把结果交回来。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/subtask 先把刚才那些改动的单元测试写出来，我这边继续改实现</span></span></code></pre></div><p>它会在输入框下方的面板里跑，你继续干活，不打架。同一个起点还能分多个叉去试不同方案。</p><div class="tip custom-block"><p class="custom-block-title">一个判断</p><p><strong>&quot;这事需要它知道我们刚才的讨论&quot;</strong> → 用 <code>/subtask</code>；<strong>&quot;这事从头讲得清楚&quot;</strong> → 用普通子代理。</p></div><h2 id="更重的手段-并行会话与-worktree" tabindex="-1">更重的手段：并行会话与 worktree <a class="header-anchor" href="#更重的手段-并行会话与-worktree" aria-label="Permalink to &quot;更重的手段：并行会话与 worktree&quot;">​</a></h2><p>当你要同时推进几条<strong>互不相干的线</strong>，子代理就不够了，得上多会话。</p><table tabindex="0"><thead><tr><th>手段</th><th>是什么</th><th>什么时候用</th></tr></thead><tbody><tr><td><code>/background</code></td><td>把当前会话分离到后台，释放终端</td><td>一个长任务，你想先干别的</td></tr><tr><td><code>claude agents</code></td><td>一个屏幕看所有后台会话在干什么</td><td>同时开了好几个会话</td></tr><tr><td><code>/fork</code></td><td>复制当前会话到新的后台会话</td><td>想从同一处出发试两条路</td></tr><tr><td>git worktree</td><td>每个会话一个独立工作目录，改动互不干扰</td><td>同一仓库并行改代码，<strong>必用</strong></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-a</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 在独立 worktree 里开会话</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">没有 worktree 就别并行改同一个仓库</p><p>两个会话在同一个目录里改文件，会互相覆盖，且很难查。并行改代码一定配 worktree。</p></div><h2 id="成本与上下文提醒" tabindex="-1">成本与上下文提醒 <a class="header-anchor" href="#成本与上下文提醒" aria-label="Permalink to &quot;成本与上下文提醒&quot;">​</a></h2><ul><li>子代理的请求<strong>计入你的用量</strong>，和主对话同一份额度</li><li>每个 subagent 的 <code>description</code> 会在启动时加载进上下文。所有子代理描述加起来超过 15000 token 会报警告——所以描述写简短，细节放进正文</li><li>子代理可以再派子代理，但最多三层</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Claude 不派我建好的子代理？</strong></p><p>A: 九成是 <code>description</code> 写得太含糊。改成&quot;在什么情况下用它&quot;的具体描述，比如「在完成一个功能、准备提交前使用」，而不是「一个代码审查者」。</p><p><strong>Q: 子代理卡在权限提示上？</strong></p><p>A: 它的提示会转到主会话里显示。看到就批，或者给它设只读工具集避免这类请求。</p><p><strong>Q: 子代理和 Skill 该选哪个？</strong></p><p>A: Skill 是<strong>写好的提示词/流程</strong>，在主对话里跑；Subagent 是<strong>独立的执行单元</strong>，在自己的上下文里跑并只回结论。要隔离噪音选 subagent，要复用话术选 skill（第十四章）。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>让它做一件&quot;会读很多文件&quot;的活，观察对话里出现的子代理调用行</li><li>用自然语言让 Claude 帮你创建一个只读的 <code>doc-checker</code> 子代理</li><li>用 <code>/subtask</code> 派一个旁支任务，主对话继续干别的</li><li>用 <code>claude --worktree test-a</code> 在独立目录里开一个会话，<code>git worktree list</code> 看看它建了什么</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p><a href="/claude-code-guide/guide/5-next-steps/20-next-steps.html">👉 第二十章：继续学习之路</a></p>`,58)])])}const g=a(d,[["render",o]]);export{u as __pageData,g as default};
